#!/usr/bin/env bash
# =============================================================================
#  FreeScout Sync Manager - agent installer (run on each FreeScout server)
#  Generated by the manager at __MANAGER_URL__
#
#  Usage:  sudo bash install-agent.sh [--dir /var/www/freescout] [--name NAME] [--from MANAGER_IP]
#    --dir   FreeScout install directory (auto-detected if omitted)
#    --name  only for several FreeScout installs on one server (lowercase, a-z0-9)
#    --from  only accept the manager's key from this IP/CIDR (recommended)
# =============================================================================
set -Eeuo pipefail
MANAGER_PUBKEY='__MANAGER_PUBKEY__'
DEFAULT_FROM='__MANAGER_FROM__'

die() { echo -e "\033[1;31m[FATAL]\033[0m $*" >&2; exit 1; }
ok()  { echo -e "  \033[1;32m✓\033[0m $*"; }
[[ $EUID -eq 0 ]] || die "Run as root (sudo)."

FS_DIR=""; NAME=""; FROM="$DEFAULT_FROM"
while [[ $# -gt 0 ]]; do
  case $1 in
    --dir) FS_DIR=${2%/}; shift 2;;
    --name) NAME=$2; shift 2;;
    --from) FROM=$2; shift 2;;
    *) die "unknown option $1";;
  esac
done
[[ -z $NAME || $NAME =~ ^[a-z0-9]{1,16}$ ]] || die "--name must be 1-16 chars a-z0-9"
[[ -z $FROM || $FROM =~ ^[0-9A-Fa-f.:/,]+$ ]] || die "--from must be an IP, CIDR or comma list"

if [[ -z $FS_DIR ]]; then
  for d in /var/www/freescout /var/www/html /var/www/helpdesk; do [[ -f $d/artisan && -f $d/.env ]] && { FS_DIR=$d; break; }; done
fi
[[ -n $FS_DIR && -f $FS_DIR/artisan && -f $FS_DIR/.env ]] || die "FreeScout not found - pass --dir /path/to/freescout"
grep -qE '^DB_CONNECTION=.*pgsql' "$FS_DIR/.env" && die "PostgreSQL FreeScout installs are not supported (MySQL/MariaDB only)"

SUFFIX=${NAME:+-$NAME}
AGENT_USER="fsagent$SUFFIX"
CONF="/etc/fs-agent$SUFFIX.conf"

echo "Installing FreeScout Sync Manager agent"
echo "  FreeScout dir : $FS_DIR"
echo "  SSH user      : $AGENT_USER"
echo "  Allowed from  : ${FROM:-any address}"

export DEBIAN_FRONTEND=noninteractive
need=(); for c in rsync gzip curl sudo; do command -v "$c" >/dev/null || need+=("$c"); done
command -v mariadb-dump >/dev/null || command -v mysqldump >/dev/null || need+=(mariadb-client)
if (( ${#need[@]} )); then apt-get update -q >/dev/null && apt-get install -y -q "${need[@]}" >/dev/null; ok "installed: ${need[*]}"; fi
command -v sshd >/dev/null || { apt-get install -y -q openssh-server >/dev/null; ok "installed openssh-server"; }

# Agent programs
echo '__AGENT_B64__'     | base64 -d >/usr/local/sbin/fs-agent
echo '__AGENT_SSH_B64__' | base64 -d >/usr/local/sbin/fs-agent-ssh
chown root:root /usr/local/sbin/fs-agent /usr/local/sbin/fs-agent-ssh
chmod 755 /usr/local/sbin/fs-agent /usr/local/sbin/fs-agent-ssh
ok "fs-agent $(/usr/local/sbin/fs-agent version 2>/dev/null || echo installed)"

# Config (root-only)
cat >"$CONF" <<EOF
# FreeScout Sync Manager agent configuration
FS_DIR=$FS_DIR
FS_USER=www-data
STATE_DIR=/var/lib/fs-agent
SAFETY_DIR=/var/backups/fs-agent
SAFETY_KEEP=3
EOF
chmod 600 "$CONF"; chown root:root "$CONF"
ok "config $CONF"

# Locked-down SSH user: key only, forced command, no shell/pty/forwarding
if ! id "$AGENT_USER" >/dev/null 2>&1; then
  useradd --system --create-home --home-dir "/var/lib/$AGENT_USER" --shell /bin/bash "$AGENT_USER"
fi
passwd -l "$AGENT_USER" >/dev/null 2>&1 || true
H=$(getent passwd "$AGENT_USER" | cut -d: -f6)
install -d -m 750 -o root -g "$AGENT_USER" "$H/.ssh"   # root-owned: the user cannot swap its own key/options
FORCED="/usr/local/sbin/fs-agent-ssh"; [[ -n $NAME ]] && FORCED="$FORCED --conf $CONF"
OPTS="restrict,command=\"$FORCED\""; [[ -n $FROM ]] && OPTS="$OPTS,from=\"$FROM\""
echo "$OPTS $MANAGER_PUBKEY" >"$H/.ssh/authorized_keys"
chown root:"$AGENT_USER" "$H/.ssh/authorized_keys"; chmod 640 "$H/.ssh/authorized_keys"
ok "SSH key installed for $AGENT_USER (forced command, no shell)"

# sudo: this user may run only fs-agent
SUDOERS="/etc/sudoers.d/fs-agent$SUFFIX"
echo "$AGENT_USER ALL=(root) NOPASSWD: /usr/local/sbin/fs-agent" >"$SUDOERS.tmp"
visudo -cf "$SUDOERS.tmp" >/dev/null || die "sudoers validation failed"
mv "$SUDOERS.tmp" "$SUDOERS"; chmod 440 "$SUDOERS"
ok "sudo rule $SUDOERS"

# The scheduler cron entry is what standby mode pauses - make sure there is one
if ! grep -qsF "$FS_DIR/artisan schedule:run" /etc/cron.d/* /etc/crontab && ! crontab -u www-data -l 2>/dev/null | grep -qF "$FS_DIR/artisan schedule:run"; then
  echo -e "  \033[1;33m!\033[0m No cron entry runs '$FS_DIR/artisan schedule:run' - FreeScout won't fetch mail. Add one in /etc/cron.d/."
fi

# Make sure sshd allows the user (AllowUsers/AllowGroups would block it)
if sshd -T 2>/dev/null | grep -qiE '^(allowusers|allowgroups) '; then
  echo -e "  \033[1;33m!\033[0m sshd has AllowUsers/AllowGroups set - add '$AGENT_USER' there and reload sshd."
fi
systemctl enable --now ssh >/dev/null 2>&1 || systemctl enable --now sshd >/dev/null 2>&1 || true

if /usr/local/sbin/fs-agent ${NAME:+--conf "$CONF"} info >/dev/null; then ok "self-test passed"
else die "self-test failed - run: sudo /usr/local/sbin/fs-agent ${NAME:+--conf $CONF }info"; fi

IP=$(hostname -I 2>/dev/null | cut -d' ' -f1)
echo
echo "Done. In the manager, add this instance with:"
echo "  Host: ${IP:-<this server>}   Port: 22   SSH user: $AGENT_USER"
